#include "fasttext_dict.h"
#include <algorithm>
#include <fstream>
#include <sstream>
#include <cmath>
#include <iostream>

Dictionary::Dictionary() : size_(0), nwords_(0), nlabels_(0) {}

void Dictionary::readFromFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Cannot open file: " + filename);
    }

    std::string line;
    int32_t lineNum = 0;
    while (std::getline(file, line)) {
        lineNum++;
        parseInputLine(line);
    }
    file.close();
}

void Dictionary::parseInputLine(const std::string& line) {
    std::istringstream iss(line);
    std::string word;

    while (iss >> word) {
        // Check if it's a label
        if (word.substr(0, labelPrefix_.length()) == labelPrefix_) {
            addLabel(word);
        } else {
            addWord(word);
        }
    }
}

void Dictionary::addWord(const std::string& word) {
    auto it = word2id_.find(word);
    if (it != word2id_.end()) {
        word_freq_[it->second]++;
    } else {
        int32_t id = nwords_;
        word2id_[word] = id;
        id2word_.push_back(word);
        word_freq_.push_back(1);
        nwords_++;
    }
}

void Dictionary::addLabel(const std::string& label) {
    auto it = label2id_.find(label);
    if (it != label2id_.end()) {
        label_freq_[it->second]++;
    } else {
        int32_t id = nlabels_;
        label2id_[label] = id;
        id2label_.push_back(label);
        label_freq_.push_back(1);
        nlabels_++;
    }
}

int32_t Dictionary::getId(const std::string& word) const {
    auto it = word2id_.find(word);
    if (it != word2id_.end()) {
        return it->second;
    }
    return -1;
}

int32_t Dictionary::getLabelId(const std::string& label) const {
    auto it = label2id_.find(label);
    if (it != label2id_.end()) {
        return it->second;
    }
    return -1;
}

std::string Dictionary::getWord(int32_t id) const {
    if (id >= 0 && id < id2word_.size()) {
        return id2word_[id];
    }
    return "";
}

std::string Dictionary::getLabel(int32_t id) const {
    if (id >= 0 && id < id2label_.size()) {
        return id2label_[id];
    }
    return "";
}

int32_t Dictionary::getWordCount(int32_t id) const {
    if (id >= 0 && id < word_freq_.size()) {
        return word_freq_[id];
    }
    return 0;
}

int32_t Dictionary::getLabelCount(int32_t id) const {
    if (id >= 0 && id < label_freq_.size()) {
        return label_freq_[id];
    }
    return 0;
}

