#ifndef FASTTEXT_DICT_H
#define FASTTEXT_DICT_H

#include <string>
#include <vector>
#include <unordered_map>
#include <map>

class Dictionary {
public:
    Dictionary();

    void readFromFile(const std::string& filename);
    void parseInputLine(const std::string& line);

    void addWord(const std::string& word);
    void addLabel(const std::string& label);

    int32_t getId(const std::string& word) const;
    int32_t getLabelId(const std::string& label) const;

    std::string getWord(int32_t id) const;
    std::string getLabel(int32_t id) const;

    int32_t getWordCount(int32_t id) const;
    int32_t getLabelCount(int32_t id) const;

    int32_t nwords() const { return nwords_; }
    int32_t nlabels() const { return nlabels_; }
    int32_t size() const { return size_; }

    void setMinCount(int32_t minCount) { minCount_ = minCount; }
    void setMinCountLabel(int32_t minCountLabel) { minCountLabel_ = minCountLabel; }
    void setLabelPrefix(const std::string& prefix) { labelPrefix_ = prefix; }

    void threshold(int32_t t, int32_t minCount);

private:
    std::unordered_map<std::string, int32_t> word2id_;
    std::unordered_map<std::string, int32_t> label2id_;
    std::vector<std::string> id2word_;
    std::vector<std::string> id2label_;
    std::vector<int32_t> word_freq_;
    std::vector<int32_t> label_freq_;

    int32_t size_;
    int32_t nwords_;
    int32_t nlabels_;
    int32_t minCount_;
    int32_t minCountLabel_;
    std::string labelPrefix_;
};

#endif
