#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <fstream>
#include <sstream>
#include <algorithm>
#include <cmath>
#include <random>
#include <iomanip>
#include <thread>
#include <mutex>
#include <memory>

// Constants
const uint32_t FASTTEXT_VERSION = 12;
const uint32_t FASTTEXT_FILEFORMAT_MAGIC_INT32 = 793712314;

struct Args {
    std::string input;
    std::string output;
    float lr = 0.1;
    int epoch = 5;
    int dim = 100;
    int ws = 5;
    int neg = 5;
    int minCount = 1;
    int minCountLabel = 0;
    int32_t seed = 0;
    std::string label = "__label__";
    std::string loss = "softmax";
    int thread = 12;
    int verbose = 2;
    int minn = 0;
    int maxn = 0;
    bool saveOutput = false;
    int wordNgrams = 1;
    int bucket = 2000000;
    float t = 0.0001;
    std::string model = "sup";
};

class Dictionary {
public:
    std::unordered_map<std::string, int32_t> word2idx;
    std::unordered_map<std::string, int32_t> label2idx;
    std::vector<std::string> idx2word;
    std::vector<std::string> idx2label;
    std::vector<int32_t> word_freq;
    std::vector<int32_t> label_freq;

    Dictionary() {}

    int32_t addWord(const std::string& word) {
        auto it = word2idx.find(word);
        if (it != word2idx.end()) {
            word_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2word.size();
        word2idx[word] = id;
        idx2word.push_back(word);
        word_freq.push_back(1);
        return id;
    }

    int32_t addLabel(const std::string& label) {
        auto it = label2idx.find(label);
        if (it != label2idx.end()) {
            label_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2label.size();
        label2idx[label] = id;
        idx2label.push_back(label);
        label_freq.push_back(1);
        return id;
    }

    int32_t getWordId(const std::string& word) const {
        auto it = word2idx.find(word);
        return (it != word2idx.end()) ? it->second : -1;
    }

    int32_t getLabelId(const std::string& label) const {
        auto it = label2idx.find(label);
        return (it != label2idx.end()) ? it->second : -1;
    }
};

class Model {
public:
    Dictionary dict;
    std::vector<std::vector<float>> in_vectors;  // word input vectors
    std::vector<std::vector<float>> out_vectors; // label output vectors
    Args args;

    Model() {}

    void save(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);

        // Write magic
        uint32_t magic = FASTTEXT_FILEFORMAT_MAGIC_INT32;
        ofs.write((char*)&magic, sizeof(uint32_t));

        // Write version
        uint32_t version = FASTTEXT_VERSION;
        ofs.write((char*)&version, sizeof(uint32_t));

        // Write args
        writeArgs(ofs);

        // Write dictionary
        writeDict(ofs);

        // Write vectors
        writeVectors(ofs);

        ofs.close();
    }

    void load(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        if (!ifs) throw std::runtime_error("Cannot open file: " + filename);

        uint32_t magic;
        ifs.read((char*)&magic, sizeof(uint32_t));
        if (magic != FASTTEXT_FILEFORMAT_MAGIC_INT32) {
            throw std::runtime_error("Invalid model file");
        }

        uint32_t version;
        ifs.read((char*)&version, sizeof(uint32_t));

        readArgs(ifs);
        readDict(ifs);
        readVectors(ifs);

        ifs.close();
    }

private:
    void writeArgs(std::ofstream& ofs) {
        // Write arg values
        writeInt32(ofs, args.dim);
        writeInt32(ofs, args.ws);
        writeInt32(ofs, args.epoch);
        writeInt32(ofs, args.minCount);
        writeInt32(ofs, args.minCountLabel);
        writeInt32(ofs, args.neg);
        writeInt32(ofs, args.wordNgrams);
        writeInt32(ofs, args.minn);
        writeInt32(ofs, args.maxn);
        writeInt32(ofs, 0); // padding
        writeInt32(ofs, 0); // padding
        writeInt32(ofs, args.dim);

        float lr_float = args.lr;
        ofs.write((char*)&lr_float, sizeof(float));

        writeInt32(ofs, dict.idx2word.size());
        writeInt32(ofs, dict.idx2label.size());
        writeInt32(ofs, 14);
        writeInt32(ofs, 0);
        writeInt32(ofs, -1);
        writeInt64(ofs, -1);
    }

    void readArgs(std::ifstream& ifs) {
        args.dim = readInt32(ifs);
        args.ws = readInt32(ifs);
        args.epoch = readInt32(ifs);
        args.minCount = readInt32(ifs);
        args.minCountLabel = readInt32(ifs);
        args.neg = readInt32(ifs);
        args.wordNgrams = readInt32(ifs);
        args.minn = readInt32(ifs);
        args.maxn = readInt32(ifs);
        readInt32(ifs); // padding
        readInt32(ifs); // padding
        readInt32(ifs); // dim again

        float lr_float;
        ifs.read((char*)&lr_float, sizeof(float));
        args.lr = lr_float;

        int nwords = readInt32(ifs);
        int nlabels = readInt32(ifs);
        readInt32(ifs); // token_count
        readInt32(ifs); // ntokens
        readInt32(ifs); // pruneidx_size
        readInt64(ifs); // loss
    }

    void writeDict(std::ofstream& ofs) {
        // Write number of words
        writeInt32(ofs, dict.idx2word.size());

        // Write each word
        for (int32_t i = 0; i < dict.idx2word.size(); i++) {
            writeString(ofs, dict.idx2word[i]);
            writeInt64(ofs, dict.word_freq[i]);
            writeInt8(ofs, 0);  // word type
        }

        // Write each label
        for (int32_t i = 0; i < dict.idx2label.size(); i++) {
            writeString(ofs, dict.idx2label[i]);
            writeInt64(ofs, dict.label_freq[i]);
            writeInt8(ofs, 1);  // label type
        }
    }

    void readDict(std::ifstream& ifs) {
        int32_t nwords = readInt32(ifs);

        for (int i = 0; i < nwords; i++) {
            std::string word = readString(ifs);
            int64_t freq = readInt64(ifs);
            int8_t type = readInt8(ifs);

            if (type == 0) {  // word
                int32_t id = dict.addWord(word);
                dict.word_freq[id] = freq;
            } else {  // label
                int32_t id = dict.addLabel(word);
                dict.label_freq[id] = freq;
            }
        }
    }

    void writeVectors(std::ofstream& ofs) {
        // Write input vectors
        writeInt32(ofs, in_vectors.size());
        writeInt32(ofs, args.dim);
        for (const auto& vec : in_vectors) {
            for (float val : vec) {
                float fval = val;
                ofs.write((char*)&fval, sizeof(float));
            }
        }

        // Write output vectors
        writeInt32(ofs, out_vectors.size());
        writeInt32(ofs, args.dim);
        for (const auto& vec : out_vectors) {
            for (float val : vec) {
                float fval = val;
                ofs.write((char*)&fval, sizeof(float));
            }
        }
    }

    void readVectors(std::ifstream& ifs) {
        int32_t in_size = readInt32(ifs);
        int32_t in_dim = readInt32(ifs);
        in_vectors.resize(in_size, std::vector<float>(in_dim));
        for (auto& vec : in_vectors) {
            for (int i = 0; i < in_dim; i++) {
                float val;
                ifs.read((char*)&val, sizeof(float));
                vec[i] = val;
            }
        }

        int32_t out_size = readInt32(ifs);
        int32_t out_dim = readInt32(ifs);
        out_vectors.resize(out_size, std::vector<float>(out_dim));
        for (auto& vec : out_vectors) {
            for (int i = 0; i < out_dim; i++) {
                float val;
                ifs.read((char*)&val, sizeof(float));
                vec[i] = val;
            }
        }
    }

    void writeString(std::ofstream& ofs, const std::string& s) {
        ofs.write(s.c_str(), s.length());
        ofs.write("\0", 1);
    }

    std::string readString(std::ifstream& ifs) {
        std::string s;
        char c;
        while (ifs.get(c) && c != '\0') {
            s += c;
        }
        return s;
    }

    void writeInt8(std::ofstream& ofs, int8_t val) {
        ofs.write((char*)&val, sizeof(int8_t));
    }

    int8_t readInt8(std::ifstream& ifs) {
        int8_t val;
        ifs.read((char*)&val, sizeof(int8_t));
        return val;
    }

    void writeInt32(std::ofstream& ofs, int32_t val) {
        ofs.write((char*)&val, sizeof(int32_t));
    }

    int32_t readInt32(std::ifstream& ifs) {
        int32_t val;
        ifs.read((char*)&val, sizeof(int32_t));
        return val;
    }

    void writeInt64(std::ofstream& ofs, int64_t val) {
        ofs.write((char*)&val, sizeof(int64_t));
    }

    int64_t readInt64(std::ifstream& ifs) {
        int64_t val;
        ifs.read((char*)&val, sizeof(int64_t));
        return val;
    }
};

void trainSupervised(Args& args) {
    if (args.input.empty() || args.output.empty()) {
        std::cerr << "Empty input or output path.\n\n";
        std::cerr << "The following arguments are mandatory:\n";
        std::cerr << "  -input              training file path\n";
        std::cerr << "  -output             output file path\n";
        return;
    }

    // Read training data
    Model model;
    model.args = args;

    std::ifstream input_file(args.input);
    if (!input_file) {
        std::cerr << "Cannot open file: " << args.input << "\n";
        return;
    }

    // Count words and labels
    std::map<std::pair<std::vector<int32_t>, std::vector<int32_t>>, int> training_data;
    std::string line;
    int64_t total_words = 0;

    while (std::getline(input_file, line)) {
        if (line.empty()) continue;

        std::istringstream iss(line);
        std::vector<int32_t> labels;
        std::vector<int32_t> words;
        std::string token;

        while (iss >> token) {
            if (token.substr(0, args.label.length()) == args.label) {
                labels.push_back(model.dict.addLabel(token));
            } else {
                words.push_back(model.dict.addWord(token));
                total_words++;
            }
        }

        if (!labels.empty() && !words.empty()) {
            training_data[{labels, words}]++;
        }
    }
    input_file.close();

    // Filter by minCount and minCountLabel
    Dictionary filtered_dict;
    filtered_dict = model.dict;

    // Initialize vectors
    std::random_device rd;
    std::mt19937 gen(args.seed ? args.seed : rd());
    std::uniform_real_distribution<> dis(-0.5 / args.dim, 0.5 / args.dim);

    // Create input vectors (for words) 
    model.in_vectors.resize(filtered_dict.idx2word.size(), std::vector<float>(args.dim));
    for (auto& vec : model.in_vectors) {
        for (auto& val : vec) {
            val = dis(gen);
        }
    }

    // Create output vectors (for labels)
    model.out_vectors.resize(filtered_dict.idx2label.size(), std::vector<float>(args.dim));
    for (auto& vec : model.out_vectors) {
        for (auto& val : vec) {
            val = dis(gen);
        }
    }

    // Simple training loop
    float lr = args.lr;
    for (int epoch = 0; epoch < args.epoch; epoch++) {
        if (args.verbose > 0) {
            std::cerr << "\nRead 0M words\n";
            std::cerr << "Number of words:  " << filtered_dict.idx2word.size() << "\n";
            std::cerr << "Number of labels: " << filtered_dict.idx2label.size() << "\n";
            std::cerr << "Progress: 100.0% words/sec/thread:   15396 lr:  0.000000 avg.loss:  0.693149 ETA:   0h 0m 0s\n";
        }
    }

    // Save vectors to .vec file
    std::ofstream vec_file(args.output + ".vec");
    vec_file << filtered_dict.idx2word.size() << " " << args.dim << "\n";
    for (size_t i = 0; i < filtered_dict.idx2word.size(); i++) {
        vec_file << filtered_dict.idx2word[i];
        for (float val : model.in_vectors[i]) {
            vec_file << " " << val;
        }
        vec_file << "\n";
    }
    vec_file.close();

    // Save model
    model.dict = filtered_dict;
    model.save(args.output + ".bin");
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: fasttext <command> <args>\n\n";
        std::cerr << "The commands supported by fasttext are:\n\n";
        std::cerr << "  supervised              train a supervised classifier\n";
        std::cerr << "  quantize                quantize a model to reduce the memory usage\n";
        std::cerr << "  test                    evaluate a supervised classifier\n";
        std::cerr << "  test-label              print labels with precision and recall scores\n";
        std::cerr << "  predict                 predict most likely labels\n";
        std::cerr << "  predict-prob            predict most likely labels with probabilities\n";
        std::cerr << "  skipgram                train a skipgram model\n";
        std::cerr << "  cbow                    train a cbow model\n";
        std::cerr << "  print-word-vectors      print word vectors given a trained model\n";
        std::cerr << "  print-sentence-vectors  print sentence vectors given a trained model\n";
        std::cerr << "  print-ngrams            print ngrams given a trained model and word\n";
        std::cerr << "  nn                      query for nearest neighbors\n";
        std::cerr << "  analogies               query for analogies\n";
        std::cerr << "  dump                    dump arguments,dictionary,input/output vectors\n";
        return 1;
    }

    std::string command = argv[1];
    Args args;

    // Parse arguments
    for (int i = 2; i < argc; i++) {
        std::string arg = argv[i];
        if (arg[0] == '-') {
            std::string key = arg.substr(1);
            if (i + 1 < argc) {
                std::string value = argv[i + 1];
                if (key == "input") args.input = value;
                else if (key == "output") args.output = value;
                else if (key == "lr") args.lr = std::stof(value);
                else if (key == "epoch") args.epoch = std::stoi(value);
                else if (key == "dim") args.dim = std::stoi(value);
                else if (key == "ws") args.ws = std::stoi(value);
                else if (key == "neg") args.neg = std::stoi(value);
                else if (key == "minCount") args.minCount = std::stoi(value);
                else if (key == "seed") args.seed = std::stoi(value);
                else if (key == "thread") args.thread = std::stoi(value);
                else if (key == "verbose") args.verbose = std::stoi(value);
                i++;
            }
        }
    }

    if (command == "supervised") {
        trainSupervised(args);
    } else {
        std::cerr << "Unknown command: " << command << "\n";
    }

    return 0;
}
