            }
            scores[i] = score;
            max_score = std::max(max_score, score);
        }

        // Softmax
        float sum_exp = 0.0f;
        for (auto& s : scores) {
            s = std::exp(s - max_score);
            sum_exp += s;
        }
        for (auto& s : scores) {
            s /= sum_exp;
        }

        // Find best
        float best_prob = 0.0f;
        int best_label = 0;
