            std::cout << "wordNgrams " << model.args.wordNgrams << "\n";
            std::cout << "loss " << model.args.loss << "\n";
            std::cout << "model sup\n";
            std::cout << "bucket " << model.args.bucket << "\n";
            std::cout << "minn " << model.args.minn << "\n";
            std::cout << "maxn " << model.args.maxn << "\n";
            std::cout << "lrUpdateRate " << (int)model.args.lrUpdateRate << "\n";
            std::cout << "t " << model.args.t << "\n";
        } else if (option == "dict") {
            std::cout << model.dict.idx2word.size() + model.dict.idx2label.size() << "\n";
            for (size_t i = 0; i < model.dict.idx2word.size(); i++) {
                std::cout << model.dict.idx2word[i] << " " << model.dict.word_freq[i] << " word\n";
            }
            for (size_t i = 0; i < model.dict.idx2label.size(); i++) {
                std::cout << model.dict.idx2label[i] << " " << model.dict.label_freq[i] << " label\n";
            }
        }
        return 0;
    }

    else {
        std::cerr << "Unknown command: " << command << "\n";
        return 1;
    }

    return 0;
