        if (args.seed == 0) {
            std::random_device rd;
            rng.seed(rd());
        } else {
            rng.seed(args.seed);
        }

        std::uniform_real_distribution<> dis(-0.5 / args.dim, 0.5 / args.dim);

        // Initialize input vectors
        in_vectors.resize(dict.idx2word.size() + 1);  // +1 for </s>
        for (auto& vec : in_vectors) {
            vec.resize(args.dim);
            for (auto& val : vec) {
                val = dis(rng);
