        writeInt32(bin_ofs, args.wordNgrams);
        writeInt32(bin_ofs, args.minn);
        writeInt32(bin_ofs, args.maxn);
        writeInt32(bin_ofs, 0);
        writeInt32(bin_ofs, 0);
        writeInt32(bin_ofs, args.dim);

        float lr_val = args.lr;
        bin_ofs.write((char*)&lr_val, sizeof(float));

        writeInt32(bin_ofs, dict.idx2word.size());
        writeInt32(bin_ofs, dict.idx2label.size());
        writeInt32(bin_ofs, 14);
        writeInt32(bin_ofs, 0);
