            writeInt8(bin_ofs, 0);
        }

        for (size_t i = 0; i < dict.idx2label.size(); i++) {
            writeString(bin_ofs, dict.idx2label[i]);
            writeInt64(bin_ofs, dict.label_freq[i]);
            writeInt8(bin_ofs, 1);
        }

        // Write vectors
        writeInt32(bin_ofs, in_vectors.size());
        writeInt32(bin_ofs, args.dim);
        for (const auto& vec : in_vectors) {
            for (float val : vec) {
                bin_ofs.write((char*)&val, sizeof(float));
            }
        }

        writeInt32(bin_ofs, out_vectors.size());
        writeInt32(bin_ofs, args.dim);
