        }

        if (best_label >= 0 && best_label < (int)dict.idx2label.size()) {
            return dict.idx2label[best_label];
        }
        return "";
    }

    std::pair<std::string, float> predictProb(const std::string& text, int k = 1) {
        std::istringstream iss(text);
        std::vector<int32_t> words;
        std::string token;

        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) {
                words.push_back(it->second);
            }
        }

        if (words.empty() || out_vectors.empty()) {
            if (!dict.idx2label.empty()) {
                return {dict.idx2label[0], 1.0f / dict.idx2label.size()};
            }
            return {"", 0.0f};
        }

        // Average word vectors
        std::vector<float> avg_vec(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] += in_vectors[wid][i];
                }
            }
        }
        for (int i = 0; i < args.dim; i++) {
            avg_vec[i] /= std::max(1, (int)words.size());
        }

        // Find best label with softmax
        std::vector<float> scores(out_vectors.size());
        float max_score = -1e9f;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) {
                score += avg_vec[j] * out_vectors[i][j];
            }
            scores[i] = score;
            max_score = std::max(max_score, score);
        }

        // Softmax
        float sum_exp = 0.0f;
        for (auto& s : scores) {
            s = std::exp(std::min(s - max_score, 50.0f));
            sum_exp += s;
        }
        for (auto& s : scores) {
            s /= std::max(sum_exp, 1e-10f);
        }

        // Find best
        float best_prob = 0.0f;
        int best_label = 0;
        for (size_t i = 0; i < scores.size(); i++) {
            if (scores[i] > best_prob) {
                best_prob = scores[i];
                best_label = i;
            }
        }

        if (best_label >= 0 && best_label < (int)dict.idx2label.size()) {
            return {dict.idx2label[best_label], best_prob};
        }
        return {"", 0.0f};
    }

private:
    void writeString(std::ofstream& ofs, const std::string& s) {
        ofs.write(s.c_str(), s.length());
        ofs.write("\0", 1);
    }

    std::string readString(std::ifstream& ifs) {
        std::string s;
        char c;
        while (ifs.get(c) && c != '\0') {
            s += c;
        }
        return s;
    }

    void writeInt8(std::ofstream& ofs, int8_t val) {
        ofs.write((char*)&val, sizeof(int8_t));
    }

    int8_t readInt8(std::ifstream& ifs) {
        int8_t val;
        ifs.read((char*)&val, sizeof(int8_t));
        return val;
    }

    void writeInt32(std::ofstream& ofs, int32_t val) {
        ofs.write((char*)&val, sizeof(int32_t));
    }

    int32_t readInt32(std::ifstream& ifs) {
        int32_t val;
        ifs.read((char*)&val, sizeof(int32_t));
        return val;
    }

    void writeInt64(std::ofstream& ofs, int64_t val) {
        ofs.write((char*)&val, sizeof(int64_t));
    }

    int64_t readInt64(std::ifstream& ifs) {
        int64_t val;
        ifs.read((char*)&val, sizeof(int64_t));
        return val;
    }
};

void printHelp() {
    std::cerr << "usage: fasttext <command> <args>\n\n";
    std::cerr << "The commands supported by fasttext are:\n\n";
    std::cerr << "  supervised              train a supervised classifier\n";
    std::cerr << "  quantize                quantize a model to reduce the memory usage\n";
    std::cerr << "  test                    evaluate a supervised classifier\n";
    std::cerr << "  test-label              print labels with precision and recall scores\n";
    std::cerr << "  predict                 predict most likely labels\n";
    std::cerr << "  predict-prob            predict most likely labels with probabilities\n";
    std::cerr << "  skipgram                train a skipgram model\n";
    std::cerr << "  cbow                    train a cbow model\n";
    std::cerr << "  print-word-vectors      print word vectors given a trained model\n";
    std::cerr << "  print-sentence-vectors  print sentence vectors given a trained model\n";
    std::cerr << "  print-ngrams            print ngrams given a trained model and word\n";
    std::cerr << "  nn                      query for nearest neighbors\n";
    std::cerr << "  analogies               query for analogies\n";
    std::cerr << "  dump                    dump arguments,dictionary,input/output vectors\n";
}

Args parseArgs(int argc, char** argv, int start_idx) {
    Args args;
    for (int i = start_idx; i < argc; i++) {
        std::string arg = argv[i];
        if (arg[0] == '-' && i + 1 < argc) {
            std::string key = arg.substr(1);
            std::string value = argv[i + 1];

            if (key == "input") args.input = value;
            else if (key == "output") args.output = value;
            else if (key == "lr") args.lr = std::stof(value);
            else if (key == "lrUpdateRate") args.lrUpdateRate = std::stof(value);
            else if (key == "epoch") args.epoch = std::stoi(value);
            else if (key == "dim") args.dim = std::stoi(value);
            else if (key == "ws") args.ws = std::stoi(value);
            else if (key == "neg") args.neg = std::stoi(value);
            else if (key == "minCount") args.minCount = std::stoi(value);
            else if (key == "minCountLabel") args.minCountLabel = std::stoi(value);
            else if (key == "seed") args.seed = std::stoi(value);
            else if (key == "thread") args.thread = std::stoi(value);
            else if (key == "verbose") args.verbose = std::stoi(value);
            else if (key == "loss") args.loss = value;
            else if (key == "label") args.label = value;
            else if (key == "minn") args.minn = std::stoi(value);
            else if (key == "maxn") args.maxn = std::stoi(value);
            else if (key == "wordNgrams") args.wordNgrams = std::stoi(value);
            else if (key == "bucket") args.bucket = std::stoi(value);
            else if (key == "t") args.t = std::stof(value);
            i++;
        }
    }
    return args;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printHelp();
        return 1;
    }

    std::string command = argv[1];

    if (command == "supervised") {
        Args args = parseArgs(argc, argv, 2);
        if (args.input.empty() || args.output.empty()) {
            std::cerr << "Empty input or output path.\n\n";
            std::cerr << "The following arguments are mandatory:\n";
            std::cerr << "  -input              training file path\n";
            std::cerr << "  -output             output file path\n\n";
            std::cerr << "The following arguments are optional:\n";
            std::cerr << "  -verbose            verbosity level [2]\n\n";
            std::cerr << "The following arguments for the dictionary are optional:\n";
            std::cerr << "  -minCount           minimal number of word occurences [1]\n";
            std::cerr << "  -minCountLabel      minimal number of label occurences [0]\n";
            std::cerr << "  -wordNgrams         max length of word ngram [1]\n";
            std::cerr << "  -bucket             number of buckets [2000000]\n";
            std::cerr << "  -minn               min length of char ngram [0]\n";
            std::cerr << "  -maxn               max length of char ngram [0]\n";
            std::cerr << "  -t                  sampling threshold [0.0001]\n";
            std::cerr << "  -label              labels prefix [__label__]\n\n";
            std::cerr << "The following arguments for training are optional:\n";
            std::cerr << "  -lr                 learning rate [0.1]\n";
            std::cerr << "  -lrUpdateRate       change the rate of updates for the learning rate [100]\n";
            std::cerr << "  -dim                size of word vectors [100]\n";
            std::cerr << "  -ws                 size of the context window [5]\n";
            std::cerr << "  -epoch              number of epochs [5]\n";
            std::cerr << "  -neg                number of negatives sampled [5]\n";
            std::cerr << "  -loss               loss function {ns, hs, softmax, one-vs-all} [softmax]\n";
            std::cerr << "  -thread             number of threads (set to 1 to ensure reproducible results) [12]\n";
            std::cerr << "  -pretrainedVectors  pretrained word vectors for supervised learning []\n";
            std::cerr << "  -saveOutput         whether output params should be saved [false]\n";
            std::cerr << "  -seed               random generator seed  [0]\n\n";
            std::cerr << "The following arguments are for autotune:\n";
            std::cerr << "  -autotune-validation            validation file to be used for evaluation\n";
            std::cerr << "  -autotune-metric                metric objective {f1, f1:labelname} [f1]\n";
            std::cerr << "  -autotune-predictions           number of predictions used for evaluation  [1]\n";
            std::cerr << "  -autotune-duration              maximum duration in seconds [300]\n";
            std::cerr << "  -autotune-modelsize             constraint model file size [] (empty = do not quantize)\n\n";
            std::cerr << "The following arguments for quantization are optional:\n";
            std::cerr << "  -cutoff             number of words and ngrams to retain [0]\n";
            std::cerr << "  -retrain            whether embeddings are finetuned if a cutoff is applied [false]\n";
            std::cerr << "  -qnorm              whether the norm is quantized separately [false]\n";
            std::cerr << "  -qout               whether the classifier is quantized [false]\n";
            std::cerr << "  -dsub               size of each sub-vector [2]\n";
            return 0;
        }

        Model model;
        model.args = args;
        model.train(args.input);
        model.save(args.output);
        return 0;
    }

    else if (command == "predict") {
        if (argc < 3) {
            std::cerr << "usage: fasttext predict[-prob] <model> <test-data> [<k>] [<th>]\n\n";
            std::cerr << "  <model>      model filename\n";
            std::cerr << "  <test-data>  test data filename (if -, read from stdin)\n";
            std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
            std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
            return 1;
        }

        Model model;
        try {
            model.load(argv[2]);
        } catch (const std::exception& e) {
            std::cerr << "Error loading model: " << e.what() << "\n";
            return 1;
        }

        std::string line;
        if (std::string(argv[3]) == "-") {
            while (std::getline(std::cin, line)) {
                std::cout << model.predict(line) << "\n";
            }
        } else {
            std::ifstream ifs(argv[3]);
            if (!ifs) {
                std::cerr << "Cannot open file: " << argv[3] << "\n";
                return 1;
            }
            while (std::getline(ifs, line)) {
                std::cout << model.predict(line) << "\n";
            }
            ifs.close();
        }
        return 0;
    }

    else if (command == "predict-prob") {
        if (argc < 3) {
            std::cerr << "usage: fasttext predict-prob <model> <test-data> [<k>] [<th>]\n\n";
            std::cerr << "  <model>      model filename\n";
            std::cerr << "  <test-data>  test data filename (if -, read from stdin)\n";
            std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
            std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
            return 1;
        }

        Model model;
        try {
            model.load(argv[2]);
        } catch (const std::exception& e) {
            std::cerr << "Error loading model: " << e.what() << "\n";
            return 1;
        }

        int k = (argc > 4) ? std::stoi(argv[4]) : 1;

        std::string line;
        if (std::string(argv[3]) == "-") {
            while (std::getline(std::cin, line)) {
                auto [label, prob] = model.predictProb(line);
                std::cout << label << " " << std::fixed << std::setprecision(6) << prob << "\n";
            }
        } else {
            std::ifstream ifs(argv[3]);
            if (!ifs) {
                std::cerr << "Cannot open file: " << argv[3] << "\n";
                return 1;
            }
            while (std::getline(ifs, line)) {
                auto [label, prob] = model.predictProb(line);
                std::cout << label << " " << std::fixed << std::setprecision(6) << prob << "\n";
            }
            ifs.close();
        }
        return 0;
    }

    else if (command == "test") {
        if (argc < 3) {
            std::cerr << "usage: fasttext test <model> <test-data> [<k>] [<th>]\n";
            return 1;
        }

        Model model;
        try {
            model.load(argv[2]);
        } catch (const std::exception& e) {
            std::cerr << "Error loading model: " << e.what() << "\n";
            return 1;
        }

        int n = 0;
        int p1 = 0;
        int r1 = 0;

        std::string line;
        std::ifstream ifs(argv[3]);
        while (std::getline(ifs, line)) {
            std::istringstream iss(line);
            std::string token;
            std::vector<std::string> labels;
            std::string text;

            while (iss >> token) {
                if (token.substr(0, 9) == "__label__") {
                    labels.push_back(token);
                } else {
                    text += token + " ";
                }
            }

            if (!labels.empty()) {
                n++;
                std::string pred = model.predict(text);
                for (const auto& l : labels) {
                    if (pred == l) {
                        p1++;
                        r1++;
                        break;
                    }
                }
            }
        }
        ifs.close();

        std::cout << "N\t" << n << "\n";
        std::cout << "P@1\t" << (n > 0 ? (float)p1 / n : 0) << "\n";
        std::cout << "R@1\t" << (n > 0 ? (float)r1 / n : 0) << "\n";
        return 0;
    }

    else if (command == "test-label") {
        if (argc < 3) {
            std::cerr << "usage: fasttext test-label <model> <test-data> [<k>] [<th>]\n";
            return 1;
        }

        Model model;
        try {
            model.load(argv[2]);
        } catch (const std::exception& e) {
            std::cerr << "Error loading model: " << e.what() << "\n";
            return 1;
        }

        std::map<std::string, std::pair<int, int>> label_stats;
        int n = 0;
        int p1 = 0;
        int r1 = 0;

        std::string line;
        std::ifstream ifs(argv[3]);
        while (std::getline(ifs, line)) {
            std::istringstream iss(line);
            std::string token;
            std::vector<std::string> labels;
            std::string text;

            while (iss >> token) {
                if (token.substr(0, 9) == "__label__") {
                    labels.push_back(token);
                } else {
                    text += token + " ";
                }
            }

            if (!labels.empty()) {
                n++;
                std::string pred = model.predict(text);

                for (const auto& l : labels) {
                    label_stats[l].second++;
                    if (pred == l) {
                        label_stats[l].first++;
                        p1++;
                        r1++;
                    }
                }
            }
        }
        ifs.close();

        for (const auto& [label, stats] : label_stats) {
            float p = stats.second > 0 ? (float)stats.first / stats.second : 0;
            float r = stats.second > 0 ? (float)stats.first / stats.second : 0;
            float f1 = (p + r > 0) ? 2 * p * r / (p + r) : 0;
            std::cout << "F1-Score : " << std::fixed << std::setprecision(6) << f1 
                      << "  Precision : " << p 
                      << "  Recall : " << r << "   " << label << "\n";
        }

        std::cout << "N\t" << n << "\n";
        std::cout << "P@1\t" << std::fixed << std::setprecision(3) << (n > 0 ? (float)p1 / n : 0) << "\n";
        std::cout << "R@1\t" << std::fixed << std::setprecision(3) << (n > 0 ? (float)r1 / n : 0) << "\n";
        return 0;
    }

    else if (command == "dump") {
        if (argc < 3) {
            std::cerr << "usage: fasttext dump <model> <option>\n\n";
            std::cerr << "  <model>      model filename\n";
            std::cerr << "  <option>     option from args,dict,input,output\n";
            return 1;
        }

        Model model;
        try {
            model.load(argv[2]);
        } catch (const std::exception& e) {
            std::cerr << "Error loading model: " << e.what() << "\n";
            return 1;
        }

        std::string option = argc > 3 ? argv[3] : "args";

        if (option == "args") {
            std::cout << "dim " << model.args.dim << "\n";
            std::cout << "ws " << model.args.ws << "\n";
            std::cout << "epoch " << model.args.epoch << "\n";
            std::cout << "minCount " << model.args.minCount << "\n";
            std::cout << "neg " << model.args.neg << "\n";
            std::cout << "wordNgrams " << model.args.wordNgrams << "\n";
            std::cout << "loss " << model.args.loss << "\n";
            std::cout << "model sup\n";
            std::cout << "bucket " << model.args.bucket << "\n";
            std::cout << "minn " << model.args.minn << "\n";
            std::cout << "maxn " << model.args.maxn << "\n";
            std::cout << "lrUpdateRate " << (int)model.args.lrUpdateRate << "\n";
            std::cout << "t " << model.args.t << "\n";
        } else if (option == "dict") {
            std::cout << model.dict.idx2word.size() + model.dict.idx2label.size() << "\n";
            for (size_t i = 0; i < model.dict.idx2word.size(); i++) {
                std::cout << model.dict.idx2word[i] << " " << model.dict.word_freq[i] << " word\n";
            }
            for (size_t i = 0; i < model.dict.idx2label.size(); i++) {
                std::cout << model.dict.idx2label[i] << " " << model.dict.label_freq[i] << " label\n";
            }
        }
        return 0;
    }

    else {
        std::cerr << "Unknown command: " << command << "\n";
        return 1;
    }

    return 0;
}
