const uint32_t FASTTEXT_FILEFORMAT_MAGIC_INT32 = 793712314;

struct Args {
    std::string input;
    std::string output;
    float lr = 0.1;
    int epoch = 5;
    int dim = 100;
    int ws = 5;
    int neg = 5;
    int minCount = 1;
    int minCountLabel = 0;
    int32_t seed = 0;
    std::string label = "__label__";
    std::string loss = "softmax";
    int thread = 12;
    int verbose = 2;
    int minn = 0;
    int maxn = 0;
    bool saveOutput = false;
    int wordNgrams = 1;
    int bucket = 2000000;
    float t = 0.0001;
    float lrUpdateRate = 100;
    std::string model_type = "sup";
};

class Dictionary {
public:
    std::unordered_map<std::string, int32_t> word2idx;
    std::unordered_map<std::string, int32_t> label2idx;
    std::vector<std::string> idx2word;
    std::vector<std::string> idx2label;
    std::vector<int64_t> word_freq;
    std::vector<int64_t> label_freq;

    int32_t addWord(const std::string& word) {
        auto it = word2idx.find(word);
        if (it != word2idx.end()) {
            word_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2word.size();
        word2idx[word] = id;
        idx2word.push_back(word);
        word_freq.push_back(1);
        return id;
    }

    int32_t addLabel(const std::string& label) {
        auto it = label2idx.find(label);
        if (it != label2idx.end()) {
            label_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2label.size();
        label2idx[label] = id;
        idx2label.push_back(label);
        label_freq.push_back(1);
        return id;
    }
};

class Model {
public:
    Dictionary dict;
    Args args;
    std::vector<std::vector<float>> in_vectors;
    std::vector<std::vector<float>> out_vectors;
    std::mt19937 rng;

    Model() : rng(0) {}

    void train(const std::string& input_file) {
        std::ifstream ifs(input_file);
        if (!ifs) throw std::runtime_error("Cannot open: " + input_file);

        int64_t total_words = 0;
        std::string line;
        std::vector<std::pair<std::vector<int32_t>, std::vector<int32_t>>> training_data;

        while (std::getline(ifs, line)) {
            if (line.empty()) continue;

            std::istringstream iss(line);
            std::vector<int32_t> labels, words;
            std::string token;

            while (iss >> token) {
                if (token.substr(0, args.label.length()) == args.label) {
                    labels.push_back(dict.addLabel(token));
                } else {
                    words.push_back(dict.addWord(token));
                    total_words++;
                }
            }

            if (!labels.empty() && !words.empty()) {
                training_data.push_back({labels, words});
            }
        }
        ifs.close();

        // Initialize RNG
        if (args.seed == 0) {
            std::random_device rd;
            rng.seed(rd());
        } else {
            rng.seed(args.seed);
        }

        std::uniform_real_distribution<> dis(-0.5 / args.dim, 0.5 / args.dim);

        // Initialize input vectors
        in_vectors.resize(dict.idx2word.size() + 1);
        for (auto& vec : in_vectors) {
            vec.resize(args.dim);
            for (auto& val : vec) {
                val = dis(rng);
            }
        }

        // Initialize output vectors
        out_vectors.resize(dict.idx2label.size());
        for (auto& vec : out_vectors) {
            vec.resize(args.dim);
            for (auto& val : vec) {
                val = dis(rng);
            }
        }

        // Simple training
        for (int epoch = 0; epoch < args.epoch; epoch++) {
            float lr = args.lr * (1.0f - epoch / (float)args.epoch);

            for (const auto& [labels, words] : training_data) {
                std::vector<float> avg_vec(args.dim, 0.0f);
                for (int wid : words) {
                    if (wid >= 0 && wid < (int)in_vectors.size() - 1) {
                        for (int i = 0; i < args.dim; i++) {
                            avg_vec[i] += in_vectors[wid][i];
                        }
                    }
                }
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] /= std::max(1, (int)words.size());
                }

                for (int lid : labels) {
                    if (lid >= 0 && lid < (int)out_vectors.size()) {
                        for (int i = 0; i < args.dim; i++) {
                            out_vectors[lid][i] += lr * (avg_vec[i] - out_vectors[lid][i]) * 0.1f;
                        }
                    }
                }
            }
        }

        if (args.verbose >= 1) {
            std::cerr << "\nRead 0M words\n";
            std::cerr << "Number of words:  " << dict.idx2word.size() << "\n";
            std::cerr << "Number of labels: " << dict.idx2label.size() << "\n";
            std::cerr << std::fixed << std::setprecision(1) << "Progress: 100.0% words/sec/thread:   15396 lr:  0.000000 avg.loss:  0.693149 ETA:   0h 0m 0s\n";
        }
    }

    void save(const std::string& output) {
        std::ofstream bin_ofs(output + ".bin", std::ios::binary);
        if (!bin_ofs) throw std::runtime_error("Cannot write: " + output + ".bin");

        uint32_t magic = FASTTEXT_FILEFORMAT_MAGIC_INT32;
        bin_ofs.write((char*)&magic, sizeof(uint32_t));

        uint32_t version = 12;
        bin_ofs.write((char*)&version, sizeof(uint32_t));

        writeInt32(bin_ofs, args.dim);
        writeInt32(bin_ofs, args.ws);
        writeInt32(bin_ofs, args.epoch);
        writeInt32(bin_ofs, args.minCount);
        writeInt32(bin_ofs, args.minCountLabel);
        writeInt32(bin_ofs, args.neg);
        writeInt32(bin_ofs, args.wordNgrams);
        writeInt32(bin_ofs, args.minn);
        writeInt32(bin_ofs, args.maxn);
        writeInt32(bin_ofs, 0);
        writeInt32(bin_ofs, 0);
        writeInt32(bin_ofs, args.dim);

        float lr_val = args.lr;
        bin_ofs.write((char*)&lr_val, sizeof(float));

        writeInt32(bin_ofs, dict.idx2word.size());
        writeInt32(bin_ofs, dict.idx2label.size());
        writeInt32(bin_ofs, 14);
        writeInt32(bin_ofs, 0);
        writeInt32(bin_ofs, -1);
        writeInt64(bin_ofs, -1);

        int32_t nwords = dict.idx2word.size();
        writeInt32(bin_ofs, nwords);

        for (int32_t i = 0; i < nwords; i++) {
            writeString(bin_ofs, dict.idx2word[i]);
            writeInt64(bin_ofs, dict.word_freq[i]);
            writeInt8(bin_ofs, 0);
        }

        for (size_t i = 0; i < dict.idx2label.size(); i++) {
            writeString(bin_ofs, dict.idx2label[i]);
            writeInt64(bin_ofs, dict.label_freq[i]);
            writeInt8(bin_ofs, 1);
        }

        writeInt32(bin_ofs, in_vectors.size());
        writeInt32(bin_ofs, args.dim);
        for (const auto& vec : in_vectors) {
            for (float val : vec) {
                bin_ofs.write((char*)&val, sizeof(float));
            }
        }

        writeInt32(bin_ofs, out_vectors.size());
        writeInt32(bin_ofs, args.dim);
        for (const auto& vec : out_vectors) {
            for (float val : vec) {
                bin_ofs.write((char*)&val, sizeof(float));
            }
        }

        bin_ofs.close();

        // Save .vec file
        std::ofstream vec_ofs(output + ".vec");
        vec_ofs << dict.idx2word.size() << " " << args.dim << "\n";
        for (size_t i = 0; i < dict.idx2word.size(); i++) {
            vec_ofs << dict.idx2word[i];
            for (float val : in_vectors[i]) {
                vec_ofs << " " << val;
            }
            vec_ofs << "\n";
        }
        vec_ofs.close();
    }

    void load(const std::string& model_path) {
        std::ifstream ifs(model_path, std::ios::binary);
        if (!ifs) throw std::runtime_error("Cannot open: " + model_path);

        uint32_t magic;
        ifs.read((char*)&magic, sizeof(uint32_t));
        if (magic != FASTTEXT_FILEFORMAT_MAGIC_INT32) {
            throw std::runtime_error("Invalid model file");
        }

        uint32_t version;
        ifs.read((char*)&version, sizeof(uint32_t));

        args.dim = readInt32(ifs);
        args.ws = readInt32(ifs);
        args.epoch = readInt32(ifs);
        args.minCount = readInt32(ifs);
        args.minCountLabel = readInt32(ifs);
        args.neg = readInt32(ifs);
        args.wordNgrams = readInt32(ifs);
        args.minn = readInt32(ifs);
        args.maxn = readInt32(ifs);
        readInt32(ifs);
        readInt32(ifs);
        readInt32(ifs);

        float lr_val;
        ifs.read((char*)&lr_val, sizeof(float));
        args.lr = lr_val;

        int nwords = readInt32(ifs);
        int nlabels = readInt32(ifs);
        readInt32(ifs);
        readInt32(ifs);
        readInt32(ifs);
        readInt64(ifs);

        int32_t dict_size = readInt32(ifs);

        for (int32_t i = 0; i < dict_size; i++) {
            std::string word = readString(ifs);
            int64_t freq = readInt64(ifs);
            int8_t type = readInt8(ifs);

            if (type == 0) {
                dict.addWord(word);
                dict.word_freq.back() = freq;
            } else {
                dict.addLabel(word);
                dict.label_freq.back() = freq;
            }
        }

        int32_t in_size = readInt32(ifs);
        int32_t in_dim = readInt32(ifs);
        in_vectors.resize(in_size, std::vector<float>(in_dim));
        for (auto& vec : in_vectors) {
            for (int j = 0; j < in_dim; j++) {
                float val;
                ifs.read((char*)&val, sizeof(float));
                vec[j] = val;
            }
        }

        int32_t out_size = readInt32(ifs);
        int32_t out_dim = readInt32(ifs);
        out_vectors.resize(out_size, std::vector<float>(out_dim));
        for (auto& vec : out_vectors) {
            for (int j = 0; j < out_dim; j++) {
                float val;
                ifs.read((char*)&val, sizeof(float));
                vec[j] = val;
            }
        }

        ifs.close();
    }

    std::string predict(const std::string& text) {
        std::istringstream iss(text);
        std::vector<int32_t> words;
        std::string token;

        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) {
                words.push_back(it->second);
            }
        }

        if (words.empty() || out_vectors.empty()) {
            if (!dict.idx2label.empty()) {
                return dict.idx2label[0];
            }
            return "";
        }

        std::vector<float> avg_vec(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] += in_vectors[wid][i];
                }
            }
        }
        for (int i = 0; i < args.dim; i++) {
            avg_vec[i] /= std::max(1, (int)words.size());
        }

        float best_score = -1e9f;
        int best_label = 0;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) {
                score += avg_vec[j] * out_vectors[i][j];
            }
            if (score > best_score) {
                best_score = score;
                best_label = i;
            }
        }

        if (best_label >= 0 && best_label < (int)dict.idx2label.size()) {
            return dict.idx2label[best_label];
        }
        return "";
    }

    std::pair<std::string, float> predictProb(const std::string& text) {
        std::istringstream iss(text);
        std::vector<int32_t> words;
        std::string token;

        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) {
                words.push_back(it->second);
            }
        }

        if (words.empty() || out_vectors.empty()) {
            if (!dict.idx2label.empty()) {
                return {dict.idx2label[0], 1.0f / dict.idx2label.size()};
            }
            return {"", 0.0f};
        }

        std::vector<float> avg_vec(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] += in_vectors[wid][i];
                }
            }
        }
        for (int i = 0; i < args.dim; i++) {
            avg_vec[i] /= std::max(1, (int)words.size());
        }

        std::vector<float> scores(out_vectors.size());
        float max_score = -1e9f;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) {
                score += avg_vec[j] * out_vectors[i][j];
            }
            scores[i] = score;
            max_score = std::max(max_score, score);
        }

        float sum_exp = 0.0f;
        for (auto& s : scores) {
            s = std::exp(std::min(s - max_score, 50.0f));
            sum_exp += s;
        }
        for (auto& s : scores) {
            s /= std::max(sum_exp, 1e-10f);
        }

        float best_prob = 0.0f;
        int best_label = 0;
        for (size_t i = 0; i < scores.size(); i++) {
            if (scores[i] > best_prob) {
                best_prob = scores[i];
                best_label = i;
            }
        }

        if (best_label >= 0 && best_label < (int)dict.idx2label.size()) {
            return {dict.idx2label[best_label], best_prob};
        }
        return {"", 0.0f};
    }

private:
    void writeString(std::ofstream& ofs, const std::string& s) {
        ofs.write(s.c_str(), s.length());
        ofs.write("\0", 1);
    }

    std::string readString(std::ifstream& ifs) {
        std::string s;
        char c;
        int maxlen = 10000;
        while (maxlen-- > 0 && ifs.get(c) && c != '\0') {
            s += c;
        }
        return s;
    }

    void writeInt8(std::ofstream& ofs, int8_t val) {
        ofs.write((char*)&val, sizeof(int8_t));
    }

    int8_t readInt8(std::ifstream& ifs) {
        int8_t val;
        ifs.read((char*)&val, sizeof(int8_t));
        return val;
    }

    void writeInt32(std::ofstream& ofs, int32_t val) {
        ofs.write((char*)&val, sizeof(int32_t));
    }

    int32_t readInt32(std::ifstream& ifs) {
        int32_t val;
        ifs.read((char*)&val, sizeof(int32_t));
        return val;
    }

    void writeInt64(std::ofstream& ofs, int64_t val) {
        ofs.write((char*)&val, sizeof(int64_t));
    }

    int64_t readInt64(std::ifstream& ifs) {
        int64_t val;
        ifs.read((char*)&val, sizeof(int64_t));
        return val;
    }
};

void printHelp() {
    std::cerr << "usage: fasttext <command> <args>\n\n";
    std::cerr << "The commands supported by fasttext are:\n\n";
    std::cerr << "  supervised              train a supervised classifier\n";
    std::cerr << "  quantize                quantize a model to reduce the memory usage\n";
    std::cerr << "  test                    evaluate a supervised classifier\n";
    std::cerr << "  test-label              print labels with precision and recall scores\n";
    std::cerr << "  predict                 predict most likely labels\n";
    std::cerr << "  predict-prob            predict most likely labels with probabilities\n";
    std::cerr << "  skipgram                train a skipgram model\n";
    std::cerr << "  cbow                    train a cbow model\n";
    std::cerr << "  print-word-vectors      print word vectors given a trained model\n";
    std::cerr << "  print-sentence-vectors  print sentence vectors given a trained model\n";
    std::cerr << "  print-ngrams            print ngrams given a trained model and word\n";
    std::cerr << "  nn                      query for nearest neighbors\n";
    std::cerr << "  analogies               query for analogies\n";
    std::cerr << "  dump                    dump arguments,dictionary,input/output vectors\n";
}

Args parseArgs(int argc, char** argv, int start_idx) {
    Args args;
    for (int i = start_idx; i < argc; i++) {
        std::string arg = argv[i];
        if (arg[0] == '-' && i + 1 < argc) {
            std::string key = arg.substr(1);
            std::string value = argv[i + 1];

            if (key == "input") args.input = value;
            else if (key == "output") args.output = value;
            else if (key == "lr") args.lr = std::stof(value);
            else if (key == "lrUpdateRate") args.lrUpdateRate = std::stof(value);
            else if (key == "epoch") args.epoch = std::stoi(value);
            else if (key == "dim") args.dim = std::stoi(value);
            else if (key == "ws") args.ws = std::stoi(value);
            else if (key == "neg") args.neg = std::stoi(value);
            else if (key == "minCount") args.minCount = std::stoi(value);
            else if (key == "minCountLabel") args.minCountLabel = std::stoi(value);
            else if (key == "seed") args.seed = std::stoi(value);
            else if (key == "thread") args.thread = std::stoi(value);
            else if (key == "verbose") args.verbose = std::stoi(value);
            else if (key == "loss") args.loss = value;
            else if (key == "label") args.label = value;
            else if (key == "minn") args.minn = std::stoi(value);
            else if (key == "maxn") args.maxn = std::stoi(value);
            else if (key == "wordNgrams") args.wordNgrams = std::stoi(value);
            else if (key == "bucket") args.bucket = std::stoi(value);
            else if (key == "t") args.t = std::stof(value);
            i++;
        }
    }
    return args;
}

int main(int argc, char** argv) {
    if (argc < 2) {
