        std::string token;

        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) {
                words.push_back(it->second);
            }
        }

        if (words.empty() || out_vectors.empty()) {
            if (!dict.idx2label.empty()) {
                return {dict.idx2label[0], 1.0f / dict.idx2label.size()};
            }
            return {"", 0.0f};
        }

        std::vector<float> avg_vec(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] += in_vectors[wid][i];
                }
            }
        }
        for (int i = 0; i < args.dim; i++) {
            avg_vec[i] /= std::max(1, (int)words.size());
        }

        std::vector<float> scores(out_vectors.size());
        float max_score = -1e9f;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) {
                score += avg_vec[j] * out_vectors[i][j];
            }
            scores[i] = score;
            max_score = std::max(max_score, score);
        }

        float sum_exp = 0.0f;
        for (auto& s : scores) {
            s = std::exp(std::min(s - max_score, 50.0f));
            sum_exp += s;
        }
        for (auto& s : scores) {
            s /= std::max(sum_exp, 1e-10f);
        }

        float best_prob = 0.0f;
        int best_label = 0;
        for (size_t i = 0; i < scores.size(); i++) {
            if (scores[i] > best_prob) {
                best_prob = scores[i];
                best_label = i;
            }
        }

        if (best_label >= 0 && best_label < (int)dict.idx2label.size()) {
            return {dict.idx2label[best_label], best_prob};
        }
        return {"", 0.0f};
    }

private:
    void writeString(std::ofstream& ofs, const std::string& s) {
        ofs.write(s.c_str(), s.length());
        ofs.write("\0", 1);
    }

    std::string readString(std::ifstream& ifs) {
        std::string s;
        char c;
        int maxlen = 10000;
        while (maxlen-- > 0 && ifs.get(c) && c != '\0') {
            s += c;
        }
        return s;
    }

    void writeInt8(std::ofstream& ofs, int8_t val) {
        ofs.write((char*)&val, sizeof(int8_t));
    }

    int8_t readInt8(std::ifstream& ifs) {
        int8_t val;
        ifs.read((char*)&val, sizeof(int8_t));
        return val;
    }

    void writeInt32(std::ofstream& ofs, int32_t val) {
        ofs.write((char*)&val, sizeof(int32_t));
    }

    int32_t readInt32(std::ifstream& ifs) {
        int32_t val;
        ifs.read((char*)&val, sizeof(int32_t));
        return val;
    }

    void writeInt64(std::ofstream& ofs, int64_t val) {
        ofs.write((char*)&val, sizeof(int64_t));
    }

    int64_t readInt64(std::ifstream& ifs) {
        int64_t val;
        ifs.read((char*)&val, sizeof(int64_t));
        return val;
    }
};

void printHelp() {
    std::cerr << "usage: fasttext <command> <args>\n\n";
    std::cerr << "The commands supported by fasttext are:\n\n";
    std::cerr << "  supervised              train a supervised classifier\n";
