    Model() : rng(0) {}

    void train(const std::string& input_file) {
        std::ifstream ifs(input_file);
        if (!ifs) throw std::runtime_error("Cannot open: " + input_file);

        int64_t total_words = 0;
        std::string line;
        std::vector<std::pair<std::vector<int32_t>, std::vector<int32_t>>> training_data;

        while (std::getline(ifs, line)) {
            if (line.empty()) continue;

            std::istringstream iss(line);
            std::vector<int32_t> labels, words;
            std::string token;

            while (iss >> token) {
