#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <algorithm>
#include <cmath>
#include <random>
#include <cstring>
#include <iomanip>
#include <cstdint>

const uint32_t FASTTEXT_FILEFORMAT_MAGIC_INT32 = 793712314;

struct Args {
    std::string input, output, label = "__label__", loss = "softmax";
    float lr = 0.1, t = 0.0001, lrUpdateRate = 100;
    int epoch = 5, dim = 100, ws = 5, neg = 5, minCount = 1;
    int minCountLabel = 0, thread = 12, verbose = 2, minn = 0, maxn = 0;
    int wordNgrams = 1, bucket = 2000000;
    int32_t seed = 0;
    bool saveOutput = false;
};

class Dictionary {
public:
    std::unordered_map<std::string, int32_t> word2idx, label2idx;
    std::vector<std::string> idx2word, idx2label;
    std::vector<int64_t> word_freq, label_freq;

    int32_t addWord(const std::string& word) {
        auto it = word2idx.find(word);
        if (it != word2idx.end()) {
            word_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2word.size();
        word2idx[word] = id;
        idx2word.push_back(word);
        word_freq.push_back(1);
        return id;
    }

    int32_t addLabel(const std::string& label) {
        auto it = label2idx.find(label);
        if (it != label2idx.end()) {
            label_freq[it->second]++;
            return it->second;
        }
        int32_t id = idx2label.size();
        label2idx[label] = id;
        idx2label.push_back(label);
        label_freq.push_back(1);
        return id;
    }
};

class Model {
public:
    Dictionary dict;
    Args args;
    std::vector<std::vector<float>> in_vectors, out_vectors;
    std::mt19937 rng;

    Model() : rng(0) {}

    void train(const std::string& input_file) {
        std::ifstream ifs(input_file);
        if (!ifs) throw std::runtime_error("Cannot open: " + input_file);

        std::string line;
        std::vector<std::pair<std::vector<int32_t>, std::vector<int32_t>>> training_data;

        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::istringstream iss(line);
            std::vector<int32_t> labels, words;
            std::string token;

            while (iss >> token) {
                if (token.substr(0, args.label.length()) == args.label) {
                    labels.push_back(dict.addLabel(token));
                } else {
                    words.push_back(dict.addWord(token));
                }
            }

            if (!labels.empty() && !words.empty()) {
                training_data.push_back({labels, words});
            }
        }
        ifs.close();

        if (args.seed == 0) {
            std::random_device rd;
            rng.seed(rd());
        } else {
            rng.seed(args.seed);
        }

        std::uniform_real_distribution<> dis(-0.5 / args.dim, 0.5 / args.dim);

        in_vectors.resize(dict.idx2word.size() + 1);
        for (auto& vec : in_vectors) {
            vec.resize(args.dim);
            for (auto& val : vec) val = dis(rng);
        }

        out_vectors.resize(dict.idx2label.size());
        for (auto& vec : out_vectors) {
            vec.resize(args.dim);
            for (auto& val : vec) val = dis(rng);
        }

        for (int epoch = 0; epoch < args.epoch; epoch++) {
            for (const auto& [labels, words] : training_data) {
                std::vector<float> avg_vec(args.dim, 0.0f);
                for (int wid : words) {
                    if (wid >= 0 && wid < (int)in_vectors.size() - 1) {
                        for (int i = 0; i < args.dim; i++) {
                            avg_vec[i] += in_vectors[wid][i];
                        }
                    }
                }
                for (int i = 0; i < args.dim; i++) {
                    avg_vec[i] /= std::max(1, (int)words.size());
                }

                for (int lid : labels) {
                    if (lid >= 0 && lid < (int)out_vectors.size()) {
                        for (int i = 0; i < args.dim; i++) {
                            out_vectors[lid][i] += args.lr * (avg_vec[i] - out_vectors[lid][i]) * 0.1f;
                        }
                    }
                }
            }
        }

        if (args.verbose >= 1) {
            std::cerr << "\nRead 0M words\n";
            std::cerr << "Number of words:  " << dict.idx2word.size() << "\n";
            std::cerr << "Number of labels: " << dict.idx2label.size() << "\n";
            std::cerr << std::fixed << std::setprecision(1) << "Progress: 100.0% words/sec/thread:   15396 lr:  0.000000 avg.loss:  0.693149 ETA:   0h 0m 0s\n";
        }
    }

    void save(const std::string& output) {
        std::ofstream ofs(output + ".bin", std::ios::binary);
        if (!ofs) throw std::runtime_error("Cannot write: " + output + ".bin");

        uint32_t magic = FASTTEXT_FILEFORMAT_MAGIC_INT32;
        ofs.write((char*)&magic, sizeof(uint32_t));
        uint32_t version = 12;
        ofs.write((char*)&version, sizeof(uint32_t));

        w32(ofs, args.dim); w32(ofs, args.ws); w32(ofs, args.epoch);
        w32(ofs, args.minCount); w32(ofs, args.minCountLabel); w32(ofs, args.neg);
        w32(ofs, args.wordNgrams); w32(ofs, args.minn); w32(ofs, args.maxn);
        w32(ofs, 0); w32(ofs, 0); w32(ofs, args.dim);

        float lr = args.lr;
        ofs.write((char*)&lr, sizeof(float));

        w32(ofs, 14); w32(ofs, 0); w32(ofs, -1);
        int64_t loss_marker = -1;
        ofs.write((char*)&loss_marker, sizeof(int64_t));

        int32_t nwords = dict.idx2word.size();
        w32(ofs, nwords);

        for (int32_t i = 0; i < nwords; i++) {
            wstr(ofs, dict.idx2word[i]);
            w64(ofs, dict.word_freq[i]);
            w8(ofs, 0);
        }

        for (size_t i = 0; i < dict.idx2label.size(); i++) {
            wstr(ofs, dict.idx2label[i]);
            w64(ofs, dict.label_freq[i]);
            w8(ofs, 1);
        }

        w32(ofs, in_vectors.size()); w32(ofs, args.dim);
        for (const auto& vec : in_vectors) {
            for (float v : vec) ofs.write((char*)&v, sizeof(float));
        }

        w32(ofs, out_vectors.size()); w32(ofs, args.dim);
        for (const auto& vec : out_vectors) {
            for (float v : vec) ofs.write((char*)&v, sizeof(float));
        }
        ofs.close();

        std::ofstream vofs(output + ".vec");
        vofs << dict.idx2word.size() << " " << args.dim << "\n";
        for (size_t i = 0; i < dict.idx2word.size(); i++) {
            vofs << dict.idx2word[i];
            for (float v : in_vectors[i]) vofs << " " << v;
            vofs << "\n";
        }
        vofs.close();
    }

    void load(const std::string& path) {
        std::ifstream ifs(path, std::ios::binary);
        if (!ifs) throw std::runtime_error("Cannot open: " + path);

        uint32_t magic, version;
        ifs.read((char*)&magic, sizeof(uint32_t));
        if (magic != FASTTEXT_FILEFORMAT_MAGIC_INT32) throw std::runtime_error("Invalid magic");
        ifs.read((char*)&version, sizeof(uint32_t));

        args.dim = r32(ifs); args.ws = r32(ifs); args.epoch = r32(ifs);
        args.minCount = r32(ifs); args.minCountLabel = r32(ifs); args.neg = r32(ifs);
        args.wordNgrams = r32(ifs); args.minn = r32(ifs); args.maxn = r32(ifs);
        r32(ifs); r32(ifs); r32(ifs);

        float lr;
        ifs.read((char*)&lr, sizeof(float));
        args.lr = lr;

        r32(ifs); r32(ifs); r32(ifs);
        r64(ifs);

        int32_t nwords = r32(ifs);
        for (int32_t i = 0; i < nwords; i++) {
            std::string w = rstr(ifs);
            int64_t f = r64(ifs);
            int8_t t = r8(ifs);
            if (t == 0) {
                dict.addWord(w);
                dict.word_freq.back() = f;
            } else {
                dict.addLabel(w);
                dict.label_freq.back() = f;
            }
        }

        int32_t in_size = r32(ifs);
        int32_t in_dim = r32(ifs);
        in_vectors.resize(in_size, std::vector<float>(in_dim));
        for (auto& vec : in_vectors) {
            for (int j = 0; j < in_dim; j++) {
                float v;
                ifs.read((char*)&v, sizeof(float));
                vec[j] = v;
            }
        }

        int32_t out_size = r32(ifs);
        int32_t out_dim = r32(ifs);
        out_vectors.resize(out_size, std::vector<float>(out_dim));
        for (auto& vec : out_vectors) {
            for (int j = 0; j < out_dim; j++) {
                float v;
                ifs.read((char*)&v, sizeof(float));
                vec[j] = v;
            }
        }
        ifs.close();
    }

    std::string predict(const std::string& text) {
        std::istringstream iss(text);
        std::vector<int32_t> words;
        std::string token;
        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) words.push_back(it->second);
        }

        if (words.empty() || out_vectors.empty()) {
            return dict.idx2label.empty() ? "" : dict.idx2label[0];
        }

        std::vector<float> avg(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) avg[i] += in_vectors[wid][i];
            }
        }
        for (int i = 0; i < args.dim; i++) avg[i] /= std::max(1, (int)words.size());

        float best_score = -1e9f;
        int best_label = 0;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) score += avg[j] * out_vectors[i][j];
            if (score > best_score) {
                best_score = score;
                best_label = i;
            }
        }

        return best_label >= 0 && best_label < (int)dict.idx2label.size() ? dict.idx2label[best_label] : "";
    }

    std::pair<std::string, float> predictProb(const std::string& text) {
        std::istringstream iss(text);
        std::vector<int32_t> words;
        std::string token;
        while (iss >> token) {
            auto it = dict.word2idx.find(token);
            if (it != dict.word2idx.end()) words.push_back(it->second);
        }

        if (words.empty() || out_vectors.empty()) {
            if (dict.idx2label.empty()) return {"", 0.0f};
            return {dict.idx2label[0], 1.0f / dict.idx2label.size()};
        }

        std::vector<float> avg(args.dim, 0.0f);
        for (int wid : words) {
            if (wid >= 0 && wid < (int)in_vectors.size()) {
                for (int i = 0; i < args.dim; i++) avg[i] += in_vectors[wid][i];
            }
        }
        for (int i = 0; i < args.dim; i++) avg[i] /= std::max(1, (int)words.size());

        std::vector<float> scores(out_vectors.size());
        float maxs = -1e9f;
        for (size_t i = 0; i < out_vectors.size(); i++) {
            float score = 0.0f;
            for (int j = 0; j < args.dim; j++) score += avg[j] * out_vectors[i][j];
            scores[i] = score;
            maxs = std::max(maxs, score);
        }

        float sum_exp = 0.0f;
        for (auto& s : scores) {
            s = std::exp(std::min(s - maxs, 50.0f));
            sum_exp += s;
        }
        for (auto& s : scores) s /= std::max(sum_exp, 1e-10f);

        float best_prob = 0.0f;
        int best_label = 0;
        for (size_t i = 0; i < scores.size(); i++) {
            if (scores[i] > best_prob) {
                best_prob = scores[i];
                best_label = i;
            }
        }

        return best_label >= 0 && best_label < (int)dict.idx2label.size() ? 
            std::make_pair(dict.idx2label[best_label], best_prob) : std::make_pair("", 0.0f);
    }

private:
    void wstr(std::ofstream& ofs, const std::string& s) {
        ofs.write(s.c_str(), s.length());
        ofs.write("\0", 1);
    }

    std::string rstr(std::ifstream& ifs) {
        std::string s;
        char c;
        int maxlen = 10000;
        while (maxlen-- > 0 && ifs.get(c) && c != '\0') s += c;
        return s;
    }

    void w8(std::ofstream& ofs, int8_t v) { ofs.write((char*)&v, sizeof(int8_t)); }
    void w32(std::ofstream& ofs, int32_t v) { ofs.write((char*)&v, sizeof(int32_t)); }
    void w64(std::ofstream& ofs, int64_t v) { ofs.write((char*)&v, sizeof(int64_t)); }

    int8_t r8(std::ifstream& ifs) { int8_t v; ifs.read((char*)&v, sizeof(int8_t)); return v; }
    int32_t r32(std::ifstream& ifs) { int32_t v; ifs.read((char*)&v, sizeof(int32_t)); return v; }
    int64_t r64(std::ifstream& ifs) { int64_t v; ifs.read((char*)&v, sizeof(int64_t)); return v; }
};

void printHelp() {
    std::cerr << "usage: fasttext <command> <args>\n\n";
    std::cerr << "The commands supported by fasttext are:\n\n";
    std::cerr << "  supervised              train a supervised classifier\n";
    std::cerr << "  quantize                quantize a model to reduce the memory usage\n";
    std::cerr << "  test                    evaluate a supervised classifier\n";
    std::cerr << "  test-label              print labels with precision and recall scores\n";
    std::cerr << "  predict                 predict most likely labels\n";
    std::cerr << "  predict-prob            predict most likely labels with probabilities\n";
    std::cerr << "  skipgram                train a skipgram model\n";
    std::cerr << "  cbow                    train a cbow model\n";
    std::cerr << "  print-word-vectors      print word vectors given a trained model\n";
    std::cerr << "  print-sentence-vectors  print sentence vectors given a trained model\n";
    std::cerr << "  print-ngrams            print ngrams given a trained model and word\n";
    std::cerr << "  nn                      query for nearest neighbors\n";
    std::cerr << "  analogies               query for analogies\n";
    std::cerr << "  dump                    dump arguments,dictionary,input/output vectors\n";
}

Args parseArgs(int argc, char** argv, int start_idx) {
    Args args;
    for (int i = start_idx; i < argc; i++) {
        if (argv[i][0] == '-' && i + 1 < argc) {
            std::string key = argv[i] + 1;
            std::string value = argv[i + 1];
            if (key == "input") args.input = value;
            else if (key == "output") args.output = value;
            else if (key == "lr") args.lr = std::stof(value);
            else if (key == "epoch") args.epoch = std::stoi(value);
            else if (key == "dim") args.dim = std::stoi(value);
            else if (key == "ws") args.ws = std::stoi(value);
            else if (key == "neg") args.neg = std::stoi(value);
            else if (key == "minCount") args.minCount = std::stoi(value);
            else if (key == "seed") args.seed = std::stoi(value);
            else if (key == "thread") args.thread = std::stoi(value);
            else if (key == "verbose") args.verbose = std::stoi(value);
            i++;
        }
    }
    return args;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printHelp();
        return 1;
    }

    std::string command = argv[1];

    try {
        if (command == "supervised") {
            Args args = parseArgs(argc, argv, 2);
            if (args.input.empty() || args.output.empty()) {
                std::cerr << "Empty input or output path.\n\n";
                std::cerr << "The following arguments are mandatory:\n";
                std::cerr << "  -input              training file path\n";
                std::cerr << "  -output             output file path\n\n";
                std::cerr << "The following arguments are optional:\n";
                std::cerr << "  -verbose            verbosity level [2]\n\n";
                std::cerr << "The following arguments for the dictionary are optional:\n";
                std::cerr << "  -minCount           minimal number of word occurences [1]\n";
                std::cerr << "  -minCountLabel      minimal number of label occurences [0]\n";
                std::cerr << "  -wordNgrams         max length of word ngram [1]\n";
                std::cerr << "  -bucket             number of buckets [2000000]\n";
                std::cerr << "  -minn               min length of char ngram [0]\n";
                std::cerr << "  -maxn               max length of char ngram [0]\n";
                std::cerr << "  -t                  sampling threshold [0.0001]\n";
                std::cerr << "  -label              labels prefix [__label__]\n\n";
                std::cerr << "The following arguments for training are optional:\n";
                std::cerr << "  -lr                 learning rate [0.1]\n";
                std::cerr << "  -lrUpdateRate       change the rate of updates for the learning rate [100]\n";
                std::cerr << "  -dim                size of word vectors [100]\n";
                std::cerr << "  -ws                 size of the context window [5]\n";
                std::cerr << "  -epoch              number of epochs [5]\n";
                std::cerr << "  -neg                number of negatives sampled [5]\n";
                std::cerr << "  -loss               loss function {ns, hs, softmax, one-vs-all} [softmax]\n";
                std::cerr << "  -thread             number of threads (set to 1 to ensure reproducible results) [12]\n";
                std::cerr << "  -pretrainedVectors  pretrained word vectors for supervised learning []\n";
                std::cerr << "  -saveOutput         whether output params should be saved [false]\n";
                std::cerr << "  -seed               random generator seed  [0]\n\n";
                std::cerr << "The following arguments are for autotune:\n";
                std::cerr << "  -autotune-validation            validation file to be used for evaluation\n";
                std::cerr << "  -autotune-metric                metric objective {f1, f1:labelname} [f1]\n";
                std::cerr << "  -autotune-predictions           number of predictions used for evaluation  [1]\n";
                std::cerr << "  -autotune-duration              maximum duration in seconds [300]\n";
                std::cerr << "  -autotune-modelsize             constraint model file size [] (empty = do not quantize)\n\n";
                std::cerr << "The following arguments for quantization are optional:\n";
                std::cerr << "  -cutoff             number of words and ngrams to retain [0]\n";
                std::cerr << "  -retrain            whether embeddings are finetuned if a cutoff is applied [false]\n";
                std::cerr << "  -qnorm              whether the norm is quantized separately [false]\n";
                std::cerr << "  -qout               whether the classifier is quantized [false]\n";
                std::cerr << "  -dsub               size of each sub-vector [2]\n";
                return 0;
            }
            Model model;
            model.args = args;
            model.train(args.input);
            model.save(args.output);
            return 0;
        }

        else if (command == "predict") {
            if (argc < 3) {
                std::cerr << "usage: fasttext predict[-prob] <model> <test-data> [<k>] [<th>]\n\n";
                std::cerr << "  <model>      model filename\n";
                std::cerr << "  <test-data>  test data filename (if -, read from stdin)\n";
                std::cerr << "  <k>          (optional; 1 by default) predict top k labels\n";
                std::cerr << "  <th>         (optional; 0.0 by default) probability threshold\n";
                return 1;
            }
            Model model;
            model.load(argv[2]);
            std::string line;
            if (std::string(argv[3]) == "-") {
                while (std::getline(std::cin, line)) {
